INSERT INTO public.testes_catalogo
  (id, regiao, nome, estrutura, definicao, objetivo, como_fazer, positivo_se, referencia, ativo)
VALUES
(1, $$Joelho$$, $$Lachman$$, $$Ligamento cruzado anterior (LCA)$$, $$Teste clínico utilizado para avaliar a integridade e a estabilidade do ligamento cruzado anterior do joelho, observando a translação anterior da tíbia em relação ao fêmur.$$, $$Investigar instabilidade anterior do joelho e possíveis lesões do LCA, especialmente após trauma, entorse ou sensação de falseio.$$, $$Paciente em decúbito dorsal, com o joelho relaxado e flexionado aproximadamente entre 20° e 30°. O examinador estabiliza o fêmur e traciona anteriormente a tíbia, observando o deslocamento e a qualidade do ponto final. Comparar com o membro contralateral.$$, $$Aumento da translação anterior da tíbia em comparação ao lado oposto, ponto final amolecido ou sensação de instabilidade.$$, NULL, TRUE),
(2, $$Joelho$$, $$Gaveta Anterior (legado)$$, $$Ligamento cruzado anterior (LCA)$$, $$Registro legado do catálogo anterior. Este teste não consta na versão atualizada da ficha de MMII recebida para esta revisão.$$, $$Mantido apenas para preservar o histórico de resultados já gravados com este identificador.$$, $$Não utilizar para novos registros. Consultar a ficha atualizada e selecionar os testes ativos do catálogo.$$, $$Teste desativado; não aparece para novas avaliações.$$, NULL, FALSE),
(3, $$Joelho$$, $$Estresse em Valgo$$, $$Ligamento colateral medial (LCM)$$, $$Teste clínico utilizado para avaliar principalmente a integridade do ligamento colateral medial do joelho, responsável por contribuir para a estabilidade medial.$$, $$Avaliar estabilidade medial e identificar sinais compatíveis com lesão ou frouxidão do LCM após mecanismo de força em valgo.$$, $$Paciente em decúbito dorsal. O examinador estabiliza a região lateral do joelho e segura a perna distalmente. Aplica estresse em valgo com o joelho em extensão e também entre aproximadamente 20° e 30° de flexão. Comparar com o lado oposto.$$, $$Dor medial e/ou abertura excessiva do espaço articular medial em comparação com o membro contralateral.$$, NULL, TRUE),
(4, $$Joelho$$, $$Estresse em Varo$$, $$Ligamento colateral lateral (LCL)$$, $$Teste clínico utilizado para avaliar principalmente a integridade do ligamento colateral lateral do joelho e a estabilidade da região lateral.$$, $$Verificar estabilidade lateral e possíveis sinais de lesão ou frouxidão do LCL após mecanismo de força em varo.$$, $$Paciente em decúbito dorsal. O examinador estabiliza a região medial do joelho e segura a parte distal da perna. Aplica estresse em varo com o joelho em extensão e entre aproximadamente 20° e 30° de flexão. Comparar com o lado oposto.$$, $$Dor lateral e/ou abertura excessiva do espaço articular lateral em comparação com o lado contralateral.$$, NULL, TRUE),
(5, $$Tornozelo$$, $$Thompson$$, $$Tendão de Aquiles$$, $$Teste de compressão da panturrilha utilizado para avaliar a integridade funcional do tendão de Aquiles, responsável por transmitir a força da panturrilha ao calcâneo.$$, $$Investigar possível ruptura do tendão de Aquiles, especialmente diante de trauma, estalo súbito ou dificuldade de flexão plantar.$$, $$Paciente em decúbito ventral, com os pés para fora da maca e tornozelos livres. O examinador comprime a musculatura da panturrilha e observa o movimento produzido no pé.$$, $$Ausência ou redução importante da flexão plantar após a compressão da panturrilha.$$, NULL, TRUE),
(6, $$Tornozelo$$, $$Inclinação Talar$$, $$Complexo ligamentar lateral do tornozelo; principalmente ligamento calcaneofibular (LCF)$$, $$Teste clínico utilizado para avaliar a estabilidade ligamentar do tornozelo. Na realização em inversão, avalia principalmente o complexo ligamentar lateral.$$, $$Investigar instabilidade ligamentar lateral, especialmente após entorse por inversão, comparando a mobilidade com o tornozelo contralateral.$$, $$Paciente sentado ou em decúbito dorsal, com a perna relaxada. O examinador estabiliza a região distal da perna, segura o calcâneo e realiza a inclinação do tálus, geralmente por inversão do pé. Comparar com o outro lado.$$, $$Aumento excessivo da inclinação talar, dor ou sensação de instabilidade em comparação com o lado oposto.$$, NULL, TRUE),
(7, $$Quadril$$, $$Thomas$$, $$Flexores do quadril, principalmente iliopsoas; possível participação do reto femoral$$, $$Teste clínico utilizado para avaliar encurtamento ou contratura dos músculos flexores do quadril.$$, $$Identificar limitação da extensão do quadril associada a possível encurtamento dos flexores.$$, $$Paciente em decúbito dorsal, próximo à borda da maca. Uma perna é aproximada do tórax para estabilizar a pelve; a outra permanece relaxada. O examinador observa a posição da coxa e do joelho da perna testada.$$, $$A coxa da perna testada não consegue permanecer apoiada na maca. Se o joelho tende a estender com a coxa apoiada, pode haver participação do reto femoral.$$, NULL, TRUE),
(8, $$Quadril$$, $$FADIR$$, $$Estruturas intra-articulares do quadril; investigação de impacto femoroacetabular$$, $$Teste provocativo cujo nome corresponde a flexão, adução e rotação interna. É utilizado na investigação de impacto femoroacetabular e alterações intra-articulares.$$, $$Avaliar se a combinação de flexão, adução e rotação interna reproduz sintomas relacionados ao quadril, especialmente dor anterior ou na virilha.$$, $$Paciente em decúbito dorsal. O examinador flexiona o quadril e o joelho, realiza adução da coxa e, mantendo a flexão, executa rotação interna do quadril. A manobra deve ser realizada por profissional capacitado e sem exceder a tolerância do paciente.$$, $$Reprodução da dor familiar, principalmente na região anterior do quadril ou virilha; podem ocorrer estalido ou sensação de impacto.$$, NULL, TRUE),
(9, $$Ombro$$, $$Neer$$, $$Tendão do supraespinhal e bursa subacromial$$, $$Teste baseado no impacto mecânico passivo durante a elevação do braço em rotação interna, podendo comprimir estruturas sob o acrômio.$$, $$Avaliar sinais compatíveis com impacto subacromial.$$, $$O fisioterapeuta estabiliza a escápula e realiza elevação passiva do braço em rotação interna e flexão anterior, respeitando a tolerância do paciente.$$, $$Dor na região anterolateral do ombro durante a elevação.$$, NULL, TRUE),
(10, $$Ombro$$, $$Jobe$$, $$Tendão do músculo supraespinhal$$, $$Teste utilizado para avaliar a integridade funcional e a força do tendão do supraespinhal.$$, $$Investigar dor ou fraqueza associada ao supraespinhal.$$, $$Paciente posiciona os braços em abdução de aproximadamente 90° no plano da escápula, com polegares voltados para baixo. O examinador aplica resistência para baixo enquanto o paciente mantém a posição.$$, $$Dor ou fraqueza/incapacidade de resistir à força aplicada.$$, NULL, TRUE),
(11, $$Cotovelo$$, $$Cozen$$, $$Tendões dos músculos extensores do punho, especialmente na origem do epicôndilo lateral$$, $$Manobra clínica utilizada para investigar epicondilalgia lateral por meio da contração resistida dos extensores do punho.$$, $$Avaliar dor e possíveis alterações nos tendões extensores do punho na região do epicôndilo lateral.$$, $$Paciente sentado, cotovelo flexionado aproximadamente a 90° e antebraço pronado. O examinador estabiliza o cotovelo e solicita extensão do punho contra resistência, podendo associar desvio radial.$$, $$Dor na região do epicôndilo lateral durante a extensão resistida do punho.$$, NULL, TRUE),
(12, $$Cotovelo$$, $$Estresse em Valgo (Cotovelo)$$, $$Ligamento colateral medial (LCM) do cotovelo$$, $$Manobra clínica que avalia a integridade do ligamento colateral medial do cotovelo por meio de estresse em valgo.$$, $$Avaliar estabilidade medial e identificar possível lesão ou frouxidão ligamentar.$$, $$Paciente sentado ou em pé, com cotovelo levemente flexionado (aproximadamente 20° a 30°). O examinador estabiliza a região lateral do cotovelo, segura o antebraço e aplica força em valgo, observando a abertura e comparando com o lado oposto.$$, $$Dor na região medial, aumento da abertura articular ou frouxidão em comparação ao lado contralateral.$$, NULL, TRUE),
(13, $$Punho$$, $$Tinel$$, $$Nervo mediano no túnel do carpo$$, $$Teste de provocação neural realizado por pequenas percussões sobre o trajeto de um nervo, procurando reproduzir sintomas de irritação ou compressão.$$, $$Investigar sinais compatíveis com compressão do nervo mediano no túnel do carpo.$$, $$Paciente mantém antebraço e punho relaxados. O examinador localiza a região palmar do túnel do carpo e realiza pequenas percussões sobre o trajeto do nervo mediano.$$, $$Reprodução de formigamento, parestesia, sensação de choque ou dor no território do nervo mediano.$$, NULL, TRUE),
(14, $$Punho$$, $$Phalen$$, $$Nervo mediano no túnel do carpo$$, $$Teste provocativo utilizado principalmente na investigação da síndrome do túnel do carpo por meio da manutenção do punho em flexão.$$, $$Verificar se a posição de flexão do punho reproduz sintomas relacionados à compressão do nervo mediano.$$, $$Paciente posiciona os punhos em flexão, com as faces dorsais das mãos encostadas. A posição é mantida por aproximadamente 60 segundos, observando o surgimento ou aumento dos sintomas.$$, $$Formigamento, dormência, parestesia ou dor, principalmente na distribuição do nervo mediano.$$, NULL, TRUE),
(15, $$Coluna lombar$$, $$Lasègue$$, $$Raízes nervosas lombossacrais; investigação de irritação neural$$, $$Também chamado de elevação da perna estendida, é utilizado para investigar irritação ou compressão de raízes nervosas lombossacrais.$$, $$Verificar se o alongamento das estruturas neurais reproduz dor irradiada para o membro inferior.$$, $$Paciente em decúbito dorsal. O examinador eleva passivamente a perna com o joelho estendido, realizando flexão do quadril. A resposta deve ser interpretada em conjunto com os sintomas e demais achados.$$, $$Reprodução de dor irradiada característica, geralmente pela face posterior da perna, aproximadamente entre 30° e 70° de elevação.$$, NULL, TRUE),
(16, $$Quadril$$, $$Patrick-FABERE$$, $$Articulação do quadril e articulação sacroilíaca$$, $$Manobra de flexão, abdução e rotação externa utilizada para investigar alterações ou sintomas relacionados ao quadril e à articulação sacroilíaca.$$, $$Verificar se a combinação de movimentos provoca dor ou limitação.$$, $$Paciente em decúbito dorsal. O membro testado é posicionado em flexão, abdução e rotação externa, formando posição semelhante ao número quatro. O examinador estabiliza a pelve e aplica pressão suave sobre o joelho ou membro.$$, $$Reprodução de dor ou limitação, principalmente na região do quadril ou sacroilíaca.$$, NULL, TRUE),
(17, $$Tórax$$, $$Adams$$, $$Simetria do tronco; rastreio de escoliose$$, $$Manobra clínica rápida e não invasiva utilizada para rastrear assimetrias do tronco que podem estar relacionadas à escoliose.$$, $$Observar a simetria do tronco e a presença de gibosidade durante a flexão anterior.$$, $$Paciente em pé, realiza flexão anterior do tronco e deixa os braços soltos. O examinador observa o dorso por trás e procura assimetrias persistentes durante a flexão.$$, $$Presença de assimetria ou gibosidade que se torna evidente durante a flexão anterior.$$, NULL, TRUE),
(18, $$Tórax$$, $$Wright$$, $$Plexo braquial e estruturas vasculares do desfiladeiro torácico$$, $$Manobra de hiperabdução utilizada para investigar possíveis compressões neurovasculares na região do desfiladeiro torácico.$$, $$Observar possíveis alterações de pulso e reprodução de sintomas durante a elevação do membro superior.$$, $$Paciente sentado ou em pé. O examinador posiciona o ombro em abdução e rotação externa, elevando o braço acima da cabeça, e observa alterações de pulso e sintomas. Interpretar junto da avaliação clínica completa.$$, $$Alteração do pulso radial e/ou reprodução de sintomas como dor, formigamento ou dormência no membro superior.$$, NULL, TRUE),
(19, $$Coluna cervical$$, $$Spurling$$, $$Raízes nervosas cervicais$$, $$Manobra clínica utilizada na investigação de possível radiculopatia cervical relacionada à irritação ou compressão das raízes nervosas.$$, $$Investigar reprodução de sintomas irradiados relacionados às raízes nervosas cervicais.$$, $$Paciente sentado. O examinador posiciona a cabeça em extensão, inclinação lateral e rotação para o lado sintomático e, quando clinicamente apropriado, aplica compressão axial leve por profissional capacitado.$$, $$Reprodução de dor irradiada, formigamento ou dormência que se estende do pescoço para o membro superior.$$, NULL, TRUE),
(20, $$Coluna cervical$$, $$Distração Cervical$$, $$Estruturas nervosas da coluna cervical$$, $$Manobra clínica que utiliza tração suave para avaliar se a redução da pressão sobre estruturas cervicais alivia sintomas.$$, $$Verificar se a redução da pressão sobre estruturas cervicais proporciona alívio dos sintomas irradiados.$$, $$Paciente em decúbito dorsal. O examinador posiciona as mãos para realizar tração longitudinal suave da cabeça, observando a resposta do paciente. Deve ser realizada apenas por profissional capacitado.$$, $$Diminuição ou alívio da dor irradiada e dos sintomas neurológicos no membro superior.$$, NULL, TRUE)
